SELECT r.id, r.created_at,
        oo.code AS old_origin,
        CASE WHEN w.is_workflow THEN 'workflow_subagent' ELSE 'subagent' END AS new_origin,
        oa.code AS old_author,
        'agent' AS new_author
   FROM requests.requests r
   JOIN requests.turn_origins oo ON oo.id = r.turn_origin_id
   LEFT JOIN requests.author_kinds oa ON oa.id = r.author_kind_id
   LEFT JOIN requests.request_bodies_v b ON b.request_id = r.id
  CROSS JOIN LATERAL (
        SELECT COALESCE(b.system_text LIKE ANY(ARRAY['%running inside a workflow script%','%spawned by a workflow orchestration script%']::text[]), false)
            OR COALESCE(CASE jsonb_typeof(b.body -> 'messages' -> 0 -> 'content')
                   WHEN 'string' THEN (b.body -> 'messages' -> 0 ->> 'content') ~ '^\s*\[Workflow harness —'
                   WHEN 'array' THEN EXISTS (
                        SELECT 1
                          FROM jsonb_array_elements(b.body -> 'messages' -> 0 -> 'content') blk
                         WHERE blk ->> 'type' = 'text' AND (blk ->> 'text') ~ '^\s*\[Workflow harness —')
               END, false) AS is_workflow
       ) w
  WHERE r.id = ANY(ARRAY[425034,425037,425039,425042,425061,425081,425093,425102,425115,425127,425155,425173,425184,425194,425203,425226,425242,425255,425298,425310,425376,425397,425416,425440,425459,425466,425472,425476,425488,425497,425505,425518,425529,425537,425538,425540,425548,425553,425564,425573,425578,425588,425596,425602,425612,425621,425631,425638,425647,425651,425657,425664,425677,425686,425701,425715,425730,425747,425751,425759,425765,425767,425791,425795,425817,425821,425842,425844,425869,425902,425911,425927,425943,425959,425975,425988,425998,426019,426057,426060,426080,426103,426116,426121,426126,426135,426178,426182,426227,426230,426242,426260,426265,426272,426277,426284,426286,426296,426300,426305,426312,426349,426361,426366,426369,426371,426372,426374,426378,426386,426397,426409,426421,426423,426433,426434,426447,426448,426460,426461,426473,426474,426484,426486,426499,426504,426508,426510,426523,426524,426531,426536,426543,426552,426556,426566,426567,426576,426577,426590,426591,426605,426606,426616,426617,426641,426652,426653,426658,426673,426674,426681,426683,426703,426705,426711,426715,426716,426719,426723,426738,426756,426758,426761,426763,426766,426769,426773,426783,426834,426838,426847,426851,426853,426855,426859,426868,426872,426879,426897,426907,426929,427000,427001,427002,427009,427017,427018,427026,427037,427043,427059,427078,427089,427094,427212,427213,427238,427240,427255,427257,427271,427272,427287,427291,427313,427315,427338,427351,427356,427374,427379,427397,427400,427412,427414,427421,427424,427426,427432,427439,427444,427448,427452,427460,427481,427482,427486,427495,427515,427539,427583,427605,427687,427731,427762,427775,427808,427832,427853,427875,427912,427979,427997,428119,428120,428141,428172,428261,428270,428287,428339,428410,428417,428429,428436,428455,428509,428517,428521,428525,428533,428542,428548,428554,428555,428562,428565,428576,428584,428592,428615,428637,428656,428680,428688,428696,428712,428715,428736,428744,428763,4